P = [
"@H1|۶۲. آموزه‌ها برای آرون: سه تصمیم و یک مرز",
"@P|حکم این گزارش «عدم پیگیری» است؛ اما «استفادهٔ دانشی» توصیه می‌شود. و لذا سه «تصمیم» پیشنهاد می‌شود. این‌ها «توصیهٔ تجاری» نیستند؛ «تصمیم‌های روشی» هستند و هر یک، در «پرونده‌های تصفیه» قابل تکرار است.",
"@P|**تصمیم اول: پرونده را «بایگانی فعال» کن.** یعنی در «کتابخانهٔ دانش» با «برچسب‌های» مشخص: «تعویق»، «مهلت بی‌مکمل»، «ارزش‌گذاری غایب»، «هم‌نامی فعال» و «تصفیهٔ بی‌روایت». و در «غربال» پرونده‌های جدید، این «برچسب‌ها» به‌عنوان «هشدار» عمل می‌کنند. و «بایگانی فعال» یعنی «پرونده بسته است، اما درس باز است».",
"@P|**تصمیم دوم: «چک‌لیست هشت‌پرسشی» را در «فرآیند» بگذار.** (بخش ۴۴). هر پرونده‌ای که «سه بله» بگیرد، «اولویت پایین» می‌گیرد. و همین «فیلتر»، «هزینهٔ تحلیل» را نصف می‌کند و «دقت» را بالا می‌برد. و «چک‌لیست» باید «مکتوب» و «ثابت» باشد؛ وگرنه هر تحلیلگر «معیار» خودش را می‌سازد.",
"@P|**تصمیم سوم: «بستهٔ ارتباطی انحلال» را به‌عنوان «محصول» تعریف کن.** پنج گام بخش ۵۲، با «قالب» و «زمان‌بندی» و «نمونهٔ متن». و این، «محصولی» است که در «پرونده‌های تصفیه» «تقاضا» دارد و «عرضه» ندارد. و «تقاضا» یعنی «نهاد ناظر» و «هیئت تصفیه» به آن «نیاز» دارند؛ حتی اگر «بودجه» نداشته باشند.",
"@P|**و یک مرز:** این «محصول» نباید «وعدهٔ نجات» بدهد. چون «ارتباطات» نمی‌تواند «ناترازی» را «حل» کند؛ فقط می‌تواند «مرگ» را «قابل تحمل» کند. و اگر آرون «وعدهٔ» بیشتر بدهد، «اعتبار» خود را می‌سوزاند. و لذا در «پیشنهاد»، «دامنهٔ کار» باید «صریح» باشد: «متن، کانال، سنجش» — نه «مالی» و نه «حقوقی».",
"@P|**و یک نکتهٔ منابع:** این سه تصمیم، «هزینهٔ» مالی «قابل توجه» ندارند؛ اما «زمان» می‌خواهند: «بایگانی» یک روز، «چک‌لیست» یک هفته و «بستهٔ محصول» یک ماه. و «زمان»، «سرمایهٔ» آرون است. و لذا «اولویت» باید بر «محصول» باشد، نه «بایگانی».",
"@P|**و یک سنجه:** «موفقیت» این سه تصمیم با «سه عدد» سنجیده می‌شود: «تعداد پرونده‌های غربال‌شده»، «زمان غربال» و «تعداد بستهٔ فروخته‌شده». و «سنجش»، «تصمیم» را از «شعار» جدا می‌کند.",
"@H1|۶۳. پروندهٔ بعدی: پنج نامزد و پنج درس انتظاری",
"@P|پس از توسعه، صف پنج «نامزد» دارد: «قرض‌الحسنه رسالت»، «پالایش لاوان»، «بانک انصار» (پروندهٔ کامل)، «مؤسسهٔ اعتباری کاسپین» و «مؤسسهٔ اعتباری نور». و هر یک، «درس» متفاوتی دارد.",
"@P|**رسالت:** «قرض‌الحسنه» با «مدل مردمی» و «سهامداران» گسترده. و لذا «ارتباطات» آن «اجتماعی» است، نه «بانکی». و «ارزش دانشی» آن، در «مدل مشارکت» و «اعتماد محلی» است.",
"@P|**لاوان:** «پالایش» و «صنعت»؛ نه «بانک». و لذا «مخاطب» آن «B2B» است و «روابط عمومی» آن «صنعتی». و «مقایسه» با «خانوادهٔ بانکی» «ناممکن» است؛ اما «مقایسهٔ مدل» ممکن. و «درس انتظاری»: «روابط عمومی صنعتی» با «روابط عمومی بحران مالی» تفاوت دارد.",
"@P|**انصار:** «آخرین بانک نظامی» که در ۱۴۰۲ (طبق پروندهٔ ۱۲۴) ادغام شد. و لذا «توسعه» و «انصار» دو «سر» یک «الگو» هستند: «اولین» و «آخرین». و «مقایسه» آن‌ها، «الگو» را کامل می‌کند.",
"@P|**کاسپین:** «مؤسسهٔ» از «تجمیع» چند تعاونی، با «مخاطب» بزرگ و «پروندهٔ» پیچیده. و «ارزش دانشی» آن، در «مدیریت بحران» و «ادغام چندلایه» است.",
"@P|**نور:** «ادغام در بانک ملی» با «انتقال سپرده‌ها» (S08). و لذا «درس» آن، «مدل ادغام» است، نه «انحلال». و «مقایسه» آن با «توسعه»، «تفاوت پیام» را نشان می‌دهد: «حساب باز است» در برابر «حساب را ببندید».",
"@P|**و یک قاعدهٔ ترتیب:** «رسالت» اول است؛ چون «زنده» و «قابل دسترس» است. و «کاسپین» آخر؛ چون «داده» کم است. و همین ترتیب، بر پایهٔ «هزینهٔ تحلیل» و «ارزش دانشی» است، نه «جذابیت».",
"@P|**و یک هشدار:** در پرونده‌های «تصفیه»، «امتیاز» باید «کمتر» از ۲٫۵ باشد؛ و اگر نبود، «ناهنجاری» است و باید «توضیح» داده شود. و همین، «آزمون» روش است.",
"@H1|۶۴. نقد این گزارش: پنج ایراد ممکن",
"@P|هر گزارش «قابل نقد» است و این بخش، «پنج ایراد» را که یک خوانندهٔ منتقد می‌تواند بگیرد، پیشاپیش مطرح و ارزیابی می‌کند. و این، «دفاع» نیست؛ «شفافیت» است.",
"@P|**ایراد اول: «منابع کم است».** پاسخ: درست است؛ ۲۲ منبع و کسری ۷۸ درصدی. و «دلیل» آن در بخش ۴۱ آمده: «انحلال»، «کوچکی» و «کم‌رونقی». و لذا «حکم» بر «وضعیت حقوقی» استوار است، نه بر «جزئیات مالی». و همین، «آسیب‌پذیری» را کم می‌کند.",
"@P|**ایراد دوم: «امتیاز ساختهٔ وزن‌هاست».** پاسخ: درست است؛ و لذا «حساسیت» انجام شد و بازهٔ ۲٫۱۴ تا ۲٫۴۴ گزارش شد. و «حکم» در همهٔ سناریوها یکی است. اما «وزن‌ها» همچنان «انتخاب» هستند و «انتخاب» قابل نقد.",
"@P|**ایراد سوم: «تحلیل توصیفی است، نه علّی».** پاسخ: تا حدی درست است. «هم‌بستگی» نشان داده شد (تعلیق + مهلت + نبود کانال = بحران)، نه «علیت». و «علیت» نیازمند «مقایسهٔ کنترل‌شده» است که در «مطالعهٔ موردی» ممکن نیست. و لذا «تز» با «به نظر می‌رسد» همراه شده است.",
"@P|**ایراد چهارم: «تز بیش از داده است».** پاسخ: «تز» بر «سه سند» استوار است (پیامک، صورت‌جلسه، اظهارنظر ناظر) و «سه نشانه» دارد. اما «تعمیم» آن به «کل سازمان» یک «برداشت» است، نه «یافته». و لذا در «جمع‌بندی» (بخش ۴۷) «تز» با «شاهد» جدا شده است.",
"@P|**ایراد پنجم: «نبود شاهد میدانی».** پاسخ: درست است و در بخش ۳۹ اعلام شد. هیچ مصاحبه‌ای انجام نشد و «احساس مخاطب» از «نقل‌قول» بازسازی شد. و همین، «قدرت» تحلیل را کم می‌کند؛ اما «صداقت» را زیاد.",
"@P|**و یک ایراد ششم که خودمان می‌گیریم:** «چرا این پرونده در صف است، اگر حکم روشن است؟». پاسخ: چون «الگو» را می‌سازد. و «حکم» برای «تصمیم» است و «الگو» برای «آینده». و لذا «توسعه» را نمی‌گیریم؛ اما «درس» آن را «می‌فروشیم» — به‌صورت «محصول»، نه «مشاورهٔ موردی».",
"@P|**و یک نکته:** «اعلام ایراد» یک «انتخاب» است، نه «اجبار». و گزارش‌هایی که «ایراد» خود را نمی‌گویند، «قوی‌تر» به نظر می‌رسند و «ضعیف‌تر» هستند.",
"@H1|۶۵. واژه‌نامهٔ مخاطب: پنج نوع «طرف»",
"@P|در پروندهٔ توسعه، پنج «طرف» وجود دارد و هر یک «پرسش» و «زبان» خودش را دارد. و در «پیامک ۱۴۰۰»، همه با «یک جمله» خطاب شدند.",
"@P|**سپرده‌گذار خرد.** ماندهٔ کمتر از ۵۰ میلیون تومان (S03). پرسش: «کِی و چقدر؟». زبان: «عدد و تاریخ»، با «خط درشت». و «کانال»: پیامک و شعبه.",
"@P|**سپرده‌گذار نهادی.** شرکت یا صندوق با «وکیل». پرسش: «مبنای محاسبه و مستندات». زبان: «سند و جدول». و «کانال»: مکاتبه و جلسه.",
"@P|**سهامدار خرد.** صاحب «برگه» بدون «قیمت». پرسش: «سهم من چه شد؟». زبان: «ارزش و تصفیه». و «کانال»: اطلاعیه و پرتال.",
"@P|**کارمند.** با «دو گزینه» و «۱۹ اسفند» (S03). پرسش: «شغل و اولویت جذب». زبان: «گزینه و جدول زمانی». و «کانال»: بخشنامه و جلسه.",
"@P|**کارفرما و پذیرنده.** با «شبا» و «پایانه». پرسش: «حساب و تسویه». زبان: «فنی و کوتاه». و «کانال»: ایمیل و تماس.",
"@P|**و یک نکته:** «پنج نوع» یعنی «پنج متن». اما «پنج» لازم نیست: «سه» کافی است — «کوتاه و درشت» برای سپرده‌گذار خرد، «سندی» برای نهادی و سهامدار، و «فنی» برای کارفرما. و «کارمند» با «بخشنامه» پوشش می‌یابد.",
"@P|**و یک اشتباه رایج:** «یک متن برای همه» همیشه به «نفع قوی‌ترین» تمام می‌شود؛ چون «زبان» آن «حقوقی» است. و «ضعیف‌ترین» (سپرده‌گذار خرد) «هیچ» نمی‌گیرد. و در توسعه، همین رخ داد.",
"@H1|۶۶. سه پرسشی که هر مدیر باید بپرسد",
"@P|در پروندهٔ توسعه، سه «پرسش» وجود داشت که اگر «قبل از» تصمیم پرسیده می‌شد، «بحران» کم می‌شد. و هر سه «کوتاه» و «ارزان» بودند.",
"@P|**پرسش اول: «مخاطب من چند نفر است و چند کانال دارم؟»** در توسعه، پاسخ «نامعلوم» و «پنج کانال» بود که «چهار» آن «بی‌استفاده» ماند (بخش ۵۴). و اگر مدیر این «نسبت» را می‌دانست، «کانال» را «فعال» می‌کرد. و «دانستن»، «ابزار» است، نه «فضیلت».",
"@P|**پرسش دوم: «اگر امروز مهلتی اعلام کنم، چه کسی به پرسش‌های بعدی پاسخ می‌دهد؟»** در توسعه، «مهلت» اعلام شد («۲۵ اسفند») و «پاسخ‌دهنده» نبود. و لذا «مهلت» به «فشار» تبدیل شد و «فشار» به «صف». و «صف»، «تصویر» می‌سازد؛ و «تصویر»، «خبر» می‌شود.",
"@P|**پرسش سوم: «اگر امروز عددی منتشر نکنم، چه کسی عدد جایش می‌سازد؟»** در توسعه، «عدد» منتشر نشد («ارزش دارایی») و «بازار» عدد ساخت: «۵۰ هزار میلیارد تومان» (S21). و «عدد بازار» همیشه «بزرگ‌تر» و «بی‌سندتر» است.",
"@P|**و یک نکته:** هر سه پرسش «آینده‌نگر» هستند و «پاسخ» آن‌ها «یک صفحه» است. و لذا «نبود» آن‌ها «نبود دانش» نبود؛ «نبود عادت» بود. و «عادت»، با «چک‌لیست» ساخته می‌شود، نه با «بخشنامه».",
"@P|**و یک مقایسه:** در پرونده‌های «زنده» (فولای ۳٫۷۵، وشهر ۳٫۴۲)، هر سه پرسش «پاسخ» داشتند. و لذا «امتیاز» آن‌ها بالاتر بود. و این، «هم‌بستگی» است، نه «علیت».",
]
